mapper.select:
select
    id, gmt_create, gmt_modified, chain_id, contract_address, content_type, content_id,
    user_address, score, comment_uri, comment_hash, tx_hash, block_number, log_index, event_time
from chain_comment
where content_type = #{contentType,jdbcType=VARCHAR}
  and content_id = #{contentId,jdbcType=BIGINT}
order by block_number desc, log_index desc, id desc
limit #{offset,jdbcType=BIGINT}, #{pageSize,jdbcType=INTEGER}

select count(1)
from chain_comment
where content_type = #{contentType,jdbcType=VARCHAR}
  and content_id = #{contentId,jdbcType=BIGINT}

mapper.update:
update chain_comment
set chain_id = #{chainId,jdbcType=BIGINT},
    block_number = #{blockNumber,jdbcType=BIGINT},
    log_index = #{logIndex,jdbcType=INTEGER}
where id = #{id,jdbcType=BIGINT}
